mapper.select:
SELECT sku_id, delivery_day, min_qty, max_qty, currency, tax_price, tax_rate, disabled FROM purchase_price_change_detail WHERE is_deleted=FALSE AND purchase_price_change_id IN ( SELECT distinct ppc.id FROM purchase_price_change ppc LEFT JOIN purchase_price_change_detail ppcd ON ppc.id = ppcd.purchase_price_change_id AND ppcd.is_deleted = FALSE WHERE ppcd.supplier_id=#{supplierId} AND ppc.is_deleted=FALSE
AND ppc.approve_status IN
#{status}
)

SELECT ppcd.sku_id, ppcd.sku_no, ppcd.delivery_day, ppcd.min_qty, ppcd.max_qty, ppcd.currency, ppcd.tax_price, ppcd.tax_rate, ppcd.disabled, ppcd.effective_date, ppcd.expire_date, ppc.code as code, ppcd.purchase_price_detail_id, ppcd.purchase_price_change_id, ppcd.supplier_id FROM purchase_price_change_detail ppcd LEFT JOIN purchase_price_change ppc ON ppcd.purchase_price_change_id = ppc.id AND ppcd.is_deleted = FALSE WHERE ppc.is_deleted = FALSE
AND ppcd.purchase_price_detail_id IN
#{purchasePriceDetailId}

select ppcd.id, ppcd.sku_id, ppcd.sku_no, ppcd.delivery_day, ppcd.min_qty, ppcd.max_qty, ppcd.currency, ppcd.tax_price, ppcd.tax_rate, ppcd.disabled, ppcd.effective_date, ppcd.expire_date, ppc.code as code, ppcd.purchase_price_detail_id, ppcd.purchase_price_change_id, ppcd.supplier_id FROM purchase_price_change_detail ppcd LEFT JOIN purchase_price_change ppc ON ppcd.purchase_price_change_id = ppc.id AND ppcd.is_deleted = FALSE WHERE ppc.is_deleted = FALSE and ppc.purchase_org_id = #{purchaseOrgId}
and ppc.approve_status in
#{item}
and ppcd.supplier_id in
#{item}
and ppcd.sku_id in
#{item}
